package workbench.kotlin.l03.demo;

import java.util.Map;
import java.util.NoSuchElementException;

/**
 * Java twin of StdDelegatesDemo.kt. Java writes each behavior into the setter or getter by hand.
 */
public class StdDelegatesDemoJava {

    static final class PayoutJava {
        private String owner = "<none>";
        private int limit = 100;

        void setOwner(String owner) {
            String old = this.owner;
            this.owner = owner;                                   // observable: assign, then notify
            System.out.println("owner: " + old + " -> " + owner);
        }

        void setLimit(int limit) {
            if (limit <= 100) this.limit = limit;                 // vetoable: check, then assign
        }

        int getLimit() { return limit; }
    }

    static final class IssuerConfigJava {
        private final Map<String, Object> settings;
        IssuerConfigJava(Map<String, Object> settings) { this.settings = settings; }

        String host() { return (String) get("host"); }
        int port() { return (Integer) get("port"); }

        private Object get(String key) {
            if (!settings.containsKey(key)) throw new NoSuchElementException("Key " + key + " is missing in the map.");
            return settings.get(key);
        }
    }

    // provideDelegate has no Java twin: Java validates in the constructor, which also runs at build time
    static final class SettingsJava {
        final String issuerUrl;
        SettingsJava() {
            System.out.println("binding issuerUrl");
            issuerUrl = "value of issuerUrl";
        }
    }

    public static void main(String[] args) {
        PayoutJava p = new PayoutJava();
        p.setOwner("alice");
        p.setOwner("bob");
        p.setLimit(500);
        System.out.println("limit after veto: " + p.getLimit());
        p.setLimit(50);
        System.out.println("limit after ok: " + p.getLimit());

        IssuerConfigJava config = new IssuerConfigJava(Map.of("host", "issuer.example"));
        System.out.println("host = " + config.host());
        try {
            System.out.println("port = " + config.port());
        } catch (NoSuchElementException e) {
            System.out.println("port failed on access: " + e.getMessage());
        }

        System.out.println("building Settings...");
        SettingsJava s = new SettingsJava();
        System.out.println("built; issuerUrl = " + s.issuerUrl);
    }
}

mistake:
Swapping the target of class delegation at run time. `class Router(var gateway: Gateway) : Gateway by gateway` invites a feature flag to set `router.gateway = newGateway`:

```java
// the Java decorator people have in mind: it reads the field on every call
@Override public String authorize(Payment p) { return gateway.authorize(p); }
```

```kotlin
class Router(var gateway: Gateway) : Gateway by gateway

router.gateway = newGateway     // the property changes; authorize() still calls the old gateway
```

The assignment works, the property changes, and every call still goes to the gateway passed to the constructor, because the compiler copied it into a hidden final `$$delegate_0` field. Nothing fails; the traffic simply never moves. If the target must change, write the forwarding methods yourself so they read the property each time, or forward to an `AtomicReference<Gateway>`.

java.src:
public final class PaymentDraft {
    private final ChangeLog log;
    private String status = "NEW";
    private long amountMinor = 0;

    public PaymentDraft(ChangeLog log) { this.log = log; }

    public String getStatus() { return status; }
    public void setStatus(String s) {
        if (!s.equals(status)) log.record("status", status, s);   // repeated in every setter
        status = s;
    }

    public long getAmountMinor() { return amountMinor; }
    public void setAmountMinor(long a) {
        if (a != amountMinor) log.record("amountMinor", amountMinor, a);
        amountMinor = a;
    }
}

kotlin.src:
class Recorded<T>(private var value: T, private val log: ChangeLog) : ReadWriteProperty<Any?, T> {
    override fun getValue(thisRef: Any?, property: KProperty<*>): T = value
    override fun setValue(thisRef: Any?, property: KProperty<*>, value: T) {
        if (value != this.value) log.changes += Change(property.name, this.value, value)
        this.value = value
    }
}

class PaymentDraft(val log: ChangeLog) {
    var status: String by Recorded("NEW", log)        // the audit is written once, in Recorded
    var amountMinor: Long by Recorded(0L, log)
}

