fun <T> Map<String, Any?>.required(): PropertyDelegateProvider<Any?, ReadOnlyProperty<Any?, T>> =
    PropertyDelegateProvider { _, property ->
        // 1. check the key while the owning object is constructed
        require(property.name in this) { "missing config key '${property.name}'" }
        @Suppress("UNCHECKED_CAST")
        val value = this[property.name] as T
        // 2. the real delegate just returns what was read
        ReadOnlyProperty { _, _ -> value }
    }

class RoutingConfig(settings: Map<String, Any?>) {
    val acquirer: String by settings.required()
    val timeoutMs: Long by settings.required()
}

