RoutingConfig(Map<String, Object> settings) {
    this.acquirer = (String) require(settings, "acquirer");
    this.timeoutMs = (Long) require(settings, "timeoutMs");
}

private static Object require(Map<String, Object> m, String key) {
    if (!m.containsKey(key)) throw new IllegalArgumentException("missing config key '" + key + "'");
    return m.get(key);
}

