class Clamped(private val min: Int, private val max: Int, initial: Int) : ReadWriteProperty<Any?, Int> {
    private var value = initial.coerceIn(min, max)

    override fun getValue(thisRef: Any?, property: KProperty<*>): Int = value

    override fun setValue(thisRef: Any?, property: KProperty<*>, value: Int) {
        this.value = value.coerceIn(min, max)
    }
}

class Discount {
    var discountBps: Int by Clamped(0, 10_000, initial = 0)   // 12_000 is stored as 10_000
}

